// Resolver map — one function per field
const resolvers = {
  Query: {
    // Called when client queries "user(id: ...)"
    user: (_, { id }, context) => {
      return context.db.users.findById(id)
    },
    posts: (_, { limit = 10 }, context) => {
      return context.db.posts.findAll({ limit })
    }
  },

  Mutation: {
    createPost: (_, { input }, context) => {
      return context.db.posts.create(input)
    },
    deletePost: async (_, { id }, context) => {
      await context.db.posts.delete(id)
      return { success: true, message: 'Post deleted' }
    }
  },

  // Field-level resolver — called for every User object returned
  User: {
    posts: (user, _, context) => {
      return context.db.posts.findByAuthor(user.id)
    },
    followers: (user, _, context) => {
      return context.db.follows.findFollowers(user.id)
    }
  },

  Subscription: {
    commentAdded: {
      subscribe: (_, { postId }, context) =>
        context.pubsub.asyncIterator(`COMMENT_ADDED_${postId}`)
    }
  }
}

